// Utilidades helper
function buscarSuministro(id) {
  return suministrosData.find(s => s.Suministro === id);
}

function filtrarPorSecretaria(secretaria) {
  return suministrosData.filter(s => s.Secretaría === secretaria);
}

function filtrarPorEstado(estado) {
  return suministrosData.filter(s => s['Estados'] === estado);
}

function obtenerEstadisticas() {
  return {
    total: suministrosData.length,
    estados: [...new Set(suministrosData.map(s => s['Estados']))],
    secretarias: [...new Set(suministrosData.map(s => s.Secretaría))]
  };
}

window.SUMINISTROS_REAL_DATA = suministrosData;
